questions=[]
def add(n,topic,stem,answer,choices,notes,refs,condition=None):
 q={'id':f'ORG-GER-{n:03}','category':'老年看護学','topic':topic,'question':stem,'choices':choices.split('|'),'answer':answer,'notes':notes.split('|'),'reference_keys':['gr_'+r for r in refs.split()],'questionType':'一般問題','review_status':'checked','review_note':'記載した一次資料で論点を照合。場面の条件を明示し、正答と各誤答の理由を個別に確認。'}
 if condition:
  name,classes=condition;q['effect']={'name':name,'detail':'設問で示された状態の関連部位をゲーム内で強調します。病変の位置や重症度を断定するものではありません。','disease':True,'avatarClasses':classes,'kind':'condition'}
 assert len(q['choices'])==len(q['notes'])==4 and all(len(x)>=10 for x in q['notes']),n
 questions.append(q)
add(68,'意思決定能力の個別評価','軽度認知症の人が手術の複雑な説明を理解しにくい一方、普段の衣服や食事は自分で選んでいる。意思決定能力の理解で適切なのはどれか。',1,'決める事柄や説明方法ごとに能力を評価する|手術を理解しにくければ日常の選択も家族が決める|認知症の診断後は本人の意思確認を省く|一度の検査点数だけで今後の全ての判断を決める','能力は決める内容や環境によって異なり、支援方法も含めて個別に評価する。|複雑な医療判断の難しさから、日常生活の選択能力まで一律に否定しない。|認知症があっても本人の意思を確かめ、表明を支える。|一つの点数で固定せず、具体的な意思決定の状況を評価する。','decision')
add(69,'日常的金銭管理の支援','判断力が低下した高齢者が、支援を受ければ契約内容を理解できるが、公共料金の支払いを忘れやすい。日常生活自立支援事業の説明はどれか。',2,'裁判所が本人の全ての財産を引き取る|本人との契約に基づき日常的な金銭管理等を支える|医師が本人の通帳を自由に管理する|本人が契約を理解できなくても同意確認なしで開始する','財産を裁判所へ引き取る制度ではなく、契約に基づく生活上の支援である。|福祉サービスの利用援助や日常的な金銭管理等を本人の意思を踏まえて行う。|医師が診療の一環として自由に財産を管理する仕組みではない。|契約の内容を理解する能力等を確認し、本人と契約を結んで支援する。','welfare')
add(70,'施設職員による虐待の通報','介護施設の看護師が、同僚による入所者への暴力を目撃した。施設内で安全を確保した後、法令に基づく対応はどれか。',3,'管理者に伝えれば外部への通報は不要である|本人が退所するまで通報を待つ|速やかに市町村へ通報する|家族が告訴した後で初めて通報する','施設内の報告だけで、法令上の市町村への通報義務を満たすわけではない。|被害の継続を防ぐため、退所を待たず対応する。|養介護施設従事者には、施設従事者による虐待を受けたと思われる高齢者の発見時に市町村へ通報する義務がある。|刑事告訴の有無を条件にせず、速やかに通報する。','abuse')
add(71,'緊急やむを得ない拘束の要件','介護施設で身体拘束を例外的に検討する際、全て満たす必要がある要件の組合せはどれか。',4,'安全性・経済性・習慣性|家族の希望・職員の不足・本人の年齢|病名・入所期間・転倒歴|切迫性・非代替性・一時性','経済性や慣例を、身体拘束を例外的に行う根拠にしない。|家族の希望や人員事情、年齢だけでは要件を満たさない。|診断や転倒歴を踏まえても、それだけで拘束を決定できない。|三要件を満たすか厳格に確認し、必要な手続きと記録、継続的な見直しを行う。','restraint')
add(72,'拘束と家族の同意','家族が転倒を心配して『同意するのでベルトで固定してほしい』と希望した。介護施設の対応として適切なのはどれか。',1,'同意だけで実施せず代替方法と法定の要件を検討する|書面の同意があれば継続期間を定めなくてよい|家族が希望した場合は本人への説明を省く|同意書を保管すれば実施中の観察は不要である','家族の同意だけで正当化せず、拘束を避ける方法と例外要件を検討する。|期間と必要性を見直すことが必要で、無期限に継続しない。|本人への説明や意思の確認を家族の希望だけで省略しない。|同意の有無にかかわらず、実施中の状態と解除の可能性を確認する。','restraint')
add(73,'ベッド柵と行動制限','自分でベッドを降りられる入所者を、降りられないよう四方の柵で囲んだ。介護での身体拘束の理解として適切なのはどれか。',2,'手足に触れていなければ身体拘束ではない|用具によって自由な行動を制限する身体拘束に当たり得る|市販のベッド柵なら拘束には該当しない|転倒予防が目的なら例外要件の確認は不要である','身体に直接ベルトを巻かなくても、自由な行動を制限する場合がある。|自分で降りられなくするため四方を囲む行為は、身体拘束として検討する必要がある。|販売されている用具でも使い方と本人への影響で判断する。|安全目的であっても、拘束を避ける方法と必要性の厳格な確認が必要である。','rail restraint')
add(74,'高齢者への説明環境','難聴のある高齢者が検査説明にうなずくが内容を言い直せない。看護師の次の対応はどれか。',3,'うなずきを理解の証拠として説明を終える|家族へ同じ説明をし本人には確認しない|補聴器や周囲の音を確認して伝え直す|内容を増やし専門用語で詳しく説明する','うなずきだけでは理解を確かめられず、聞こえの条件も確認する。|家族の支援を得ても、本人に伝わる方法を検討する。|聴覚を補う用具や静かな環境を整え、分かりやすく説明して理解を確認する。|情報量や専門用語を増やすだけでは、聞こえや理解の問題を解消しにくい。','talk teach')
add(75,'退院後の介助方法の習得','退院する高齢者の配偶者が移乗介助を担う。説明を聞いて『分かりました』と答えた後の確認はどれか。',4,'署名があれば介助手順の確認を終える|手順書の全ページを暗唱してもらう|退院後にできなかった場合だけ相談を受ける|実際の介助を行ってもらい安全な動作を確認する','署名だけでは、生活の場で実行できるかを判断できない。|暗唱よりも、実際の動作と困る点の確認が重要である。|退院前に実行できるか確認し、不足があれば追加支援を整える。|説明の理解を実際の行動で確かめ、介助者の身体能力に合う方法へ調整する。','teach care')
add(76,'高齢介護者の健康','82歳の妻が84歳の夫を介護している。妻が受診や自分の服薬を後回しにしていることが分かった。支援として適切なのはどれか。',1,'妻自身の健康管理が続けられるよう代替支援を調整する|介護される夫の健康だけを計画に含める|夫が回復するまで妻の受診を延期する|妻が介護を続けたいなら健康状態は尋ねない','介護者も支援が必要な高齢者であり、受診や療養を継続できる体制を整える。|介護者の健康悪化は本人にも影響するため、両者の状況を確認する。|介護される人の回復を待って介護者の必要な診療を遅らせない。|介護を続けたい意思を尊重しながら、その健康と負担を把握する。','care')
add(77,'重い疾患と緩和ケア','高齢の慢性心不全患者が、治療を継続しながら息苦しさや不安を相談したいと話す。緩和ケアについて適切なのはどれか。',2,'心不全の治療を全てやめてから利用する|疾患の治療と並行して苦痛を和らげる支援を受けられる|がんと診断された場合だけ対象となる|本人が高齢なら身体症状の評価を省いてよい','緩和ケアは病気への治療と両立でき、全治療の中止を前提にしない。|重い疾患に伴う身体的・心理的な苦痛を、治療と並行して支える。|心不全など、がん以外の重い疾患でも支援の対象となる。|年齢にかかわらず症状を評価し、本人に合う緩和方法を検討する。','end',('慢性心不全','affected-heart'))
add(78,'終末期の口腔の不快感','最期が近い高齢者の口腔が乾燥している。覚醒が低下し安全に飲水できない。苦痛緩和の援助はどれか。',3,'コップの水を一度に流し込む|口腔ケアは回復が見込める場合だけ行う|口腔内を優しく清拭し口唇の保湿を行う|乾燥を減らすため口の中を強くこする','覚醒や嚥下が不十分な人へ無理に飲ませると誤嚥の危険がある。|回復の見通しにかかわらず、口腔の不快感を和らげるケアを行う。|状態に合った清潔と保湿によって口腔・口唇の不快感を軽減する。|粘膜を傷つけないよう、優しい方法で行う。','end')
add(79,'終末期の輸液の個別評価','最期が近い高齢者の家族が『点滴を増やせば必ず楽になりますか』と尋ねた。適切な説明はどれか。',4,'輸液量に比例して必ず苦痛が減る|輸液をしなければ必ず死期が早まる|終末期にはどの状態でも輸液を禁止する|脱水症状と水分過剰の負担を個別に評価する','輸液は症状を改善する場合もあるが、水分過剰などの負担を生む場合もある。|死期への影響を一律に断定せず、症状や本人の希望を踏まえて検討する。|状態を確認せず、全員について実施・不実施を固定しない。|利益と負担、希望を確認し、実施後も反応を評価して調整する。','hydration')
add(80,'終末期の薬剤再評価','最期が近い高齢者が多くの内服を負担に感じている。看護師の対応はどれか。',1,'現在の苦痛緩和への効果と負担を処方医へ共有する|長年飲んだ薬は目的を確認せず全て継続する|看護師の判断だけで全薬を中止する|予防目的の薬を増やすことだけを提案する','現在の目標に対する利益や投与負担を整理し、処方の見直しにつなぐ。|予防的な薬も含め、今の状況での効果と負担を再評価する。|必要な薬もあるため、本人の希望と医学的判断を踏まえチームで調整する。|苦痛の緩和と負担の軽減を含めて検討し、予防薬の追加だけに限定しない。','hydration')
add(81,'高齢糖尿病の目標設定','同じ年齢の糖尿病患者でも、一人は自立し、一人は認知症と基本的ADLの低下がある。血糖管理目標について適切なのはどれか。',2,'年齢が同じなら同一のHbA1c目標にする|認知・生活機能や低血糖リスクを含め個別に設定する|認知症があれば血糖評価そのものをやめる|合併症や支援者の有無は目標に関係しない','暦年齢だけでなく、認知機能や生活機能などに違いがある。|認知・ADL、併存疾患、使う薬や低血糖の危険などを考慮して決める。|過度な管理を避けることと、評価をしないことは異なる。|合併症や治療を支える体制も、無理なく安全に管理するための要素となる。','diabetes',('高齢者の糖尿病','affected-systemic'))
add(82,'食事減少と低血糖薬','SU薬を服用する高齢者が数日間ほとんど食べられていない。看護師が特に確認するのはどれか。',3,'服薬を続ければ低血糖は起こらないと説明する|食事不足を補うためSU薬を増量する|低血糖の徴候と服薬状況を確認し処方医へ相談する|食事量は薬の安全性と無関係として記録しない','食事摂取の減少時は、薬剤に関連した低血糖の危険を確認する。|食事不足に対して自己判断で薬を増量すると、低血糖を助長し得る。|食事量や薬剤、血糖と症状を把握し、必要な調整を医師へ相談する。|食事量の変化は低血糖リスクやシックデイの評価に重要である。','lowglucose')
add(83,'自己注射の実行能力','インスリン自己注射を続ける高齢者が、最近目盛りを読み間違え、ダイヤル操作にも時間がかかる。適切な対応はどれか。',4,'これまでできたので手技確認を省く|薬の名前を言えれば操作確認は不要とする|本人の訴えだけで投与量を増やす|視力と手の動き、実際の操作を評価して支援を調整する','加齢や疾患で機能は変化するため、以前できたことも必要に応じて再評価する。|知識だけでなく、実際に安全に実行できるか確認する。|操作の問題と必要な投与量を区別し、自己判断で増量しない。|機器を扱う能力を確認し、補助具や支援者、治療方法の相談につなぐ。','injection')
add(84,'足の観察を補う支援','糖尿病性神経障害がある高齢者は、足底の感覚が鈍く、かがんで足を見ることも難しい。支援はどれか。',1,'鏡や支援者を利用して足の傷を毎日確認する|痛みがない日は足の観察を省く|熱い湯で足の感覚を毎日確かめる|歩けている間は靴の内部を確認しない','感覚低下で傷に気づきにくいため、見えにくい部位も確認できる方法を整える。|痛みがないことは傷がない証拠にならない。|感覚が鈍い足は熱傷に気づきにくいため、熱い湯を検査代わりに使わない。|靴の異物や圧迫も傷の原因になるため、日常的に確認する。','foot',('糖尿病性神経障害','affected-systemic'))
add(85,'心不全と低栄養の両立支援','高齢の心不全患者が厳しい自己流の食事制限を続け、食事量と体重が減っている。適切な援助はどれか。',2,'塩分を避けるため総摂取量をさらに減らす|病状に合う減塩と必要な栄養の確保を専門職と調整する|心不全があれば低栄養の評価は不要とする|食事内容を見ず市販の栄養剤だけで置き換える','総量を減らすだけでは低栄養を助長し、機能低下につながり得る。|疾患の管理と低栄養の予防を両立できる内容を、医師や管理栄養士と検討する。|心不全でも栄養状態は重要であり、体重減少の理由と摂取内容を評価する。|製品を追加する場合も、必要量や病状、実際の食事を踏まえて選ぶ。','nutrition',('心不全に関する栄養管理','affected-heart'))
add(86,'心房細動と抗凝固の判断','心房細動のある高齢者が一度転倒し、家族が抗凝固薬の中止を求めた。適切な支援はどれか。',3,'年齢と転倒歴だけで直ちに中止を決める|出血の危険は確認しなくてよいと説明する|脳梗塞予防の利益と出血・転倒の危険を医師と評価する|看護師が抗凝固薬を鎮痛薬に置き換える','年齢や転倒リスクだけを理由に治療を一律に差し控えるのではない。|出血のリスクや修正できる要因も評価する必要がある。|治療の利益と負担、本人の希望を検討し、転倒予防も合わせて支える。|別の目的の薬へ看護師の判断で置き換えることはできない。','af',('心房細動','affected-heart'))
add(87,'COPDの活動とリハビリ','COPDのある高齢者は病状が安定しているが、息切れを心配しほぼ一日中座っている。適切な支援はどれか。',4,'息切れが心配なら全ての運動を中止する|同年代と同じ運動強度を一律に課す|吸入薬をやめて運動だけに変更する|状態に合った呼吸リハビリテーションを相談する','活動を一律に止めると体力や生活機能の低下につながり得る。|年齢だけでなく、病状や能力に応じた強度で行う。|薬物療法とリハビリは組み合わせて検討し、自己判断で薬をやめない。|運動訓練、呼吸法、生活上の工夫などを専門職の支援で進める。','copd',('COPD','affected-lungs'))
add(88,'パーキンソン病の立ちくらみ','パーキンソン病の高齢者が、椅子から立つと目の前が暗くなると訴える。関連して評価するのはどれか。',1,'起立に伴う血圧の変化|食後の血糖値だけ|聴力の左右差だけ|安静時の関節可動域だけ','パーキンソン病では自律神経の問題などによる起立性低血圧があり、姿勢と血圧の関係を確認する。|血糖異常も必要に応じ評価するが、立位に伴う症状では血圧の変化を捉える。|聴覚の左右差だけでは、立位に伴う眼前暗黒感の要因を評価できない。|関節機能の評価と、姿勢変化時の循環評価は別である。','pd',('パーキンソン病と起立時の症状','affected-systemic'))
add(89,'高齢者の感染徴候','高齢者が急に食事を取らなくなり、呼吸数が増えた。体温は37.0℃である。感染症の判断として適切なのはどれか。',2,'38℃未満なら感染症を除外する|発熱が目立たなくても全身状態の変化から評価する|体温が同じなら前日と同じ状態と判断する|体温が上がるまで呼吸数の記録を控える','高齢者では発熱がはっきりしない場合があり、一定の体温だけで除外しない。|普段からの変化、呼吸や食事、意識などを合わせて評価する。|同じ体温でも呼吸や摂取の変化は病状の変化を示し得る。|呼吸数の増加も重要な所見で、発熱を待たず確認する。','flu')
add(90,'心筋梗塞の非典型的な訴え','高齢の糖尿病患者に突然の冷汗、悪心、息苦しさが現れたが、胸痛は訴えていない。適切な判断はどれか。',3,'胸痛がないので心筋梗塞は除外できる|胃腸の症状だけとして次回受診まで待つ|心筋梗塞なども考え速やかに診療につなぐ|年齢による体力低下だけで説明する','心筋梗塞は典型的な胸痛を伴わない場合があり、胸痛の有無だけで除外しない。|急な全身症状があるため、消化器の問題だけと決めて待たない。|胸痛が乏しい例も考慮し、急な症状を緊急に評価する。|急な変化を加齢だけで説明せず、身体状態を確認する。','mi',('急な循環・呼吸の異常徴候','affected-systemic'))
add(91,'治療の希望の共有','高齢者が話し合った今後の治療の希望を文書にした。必要時に参照できるようにする支援はどれか。',4,'誰にも知らせず本人だけが保管する|一度文書にしたら本人にも見せない|家族が知れば医療者への共有は不要である|本人の了承を得て家族や関係する医療者と共有する','保管場所や内容が分からなければ、必要な場面で意思を支える情報として活用しにくい。|本人が内容を確認し、必要に応じて見直せるようにする。|関わる医療者にも必要な情報が伝わるよう調整する。|本人の意向に沿って共有し、異なる場面でも希望を確認できるようにする。','acp')
add(92,'高齢者のインフルエンザ予防','昨冬インフルエンザにかかった高齢者が、今季の予防は不要かと尋ねた。適切な説明はどれか。',1,'感染歴があっても今季のワクチンなど予防を相談する|一度感染すれば今後は感染しない|以前に接種したワクチンで毎年の予防は完了する|予防接種をすれば手指衛生は不要になる','流行するウイルスなどが変わり得るため、感染歴だけで今季の予防を不要としない。|過去の感染で将来の全てのインフルエンザを防げるわけではない。|接種の効果や流行株を踏まえ、各季の予防を検討する。|ワクチンに加えて日常的な感染予防も続ける。','flu')
add(93,'高齢者の性感染症予防','新しいパートナーができた高齢者が、妊娠の心配がなければ感染予防は不要かと尋ねた。適切な説明はどれか。',2,'閉経すれば性感染症にはかからない|年齢にかかわらず感染予防や必要な検査を相談する|相手の年齢が高ければ感染症は否定できる|症状がない相手には感染症がない','妊娠の可能性と性感染症への感染リスクは別である。|年齢で感染リスクはなくならず、コンドーム等や検査について相談する。|相手の年齢だけでは感染の有無を判断できない。|症状のない感染もあるため、外見や自覚症状だけで判断しない。','sex')
add(94,'高齢者の親密さの尊重','高齢者がパートナーとの親密な時間を大切にしたいと話す。看護師の姿勢として適切なのはどれか。',3,'年齢を理由に話題を変える|本人の希望より家族の価値観だけを優先する|本人の希望とプライバシーを尊重して相談を受ける|親密さの希望があるだけで認知症症状と決める','親密さや性の希望には個人差があり、高齢という理由で否定しない。|本人の意向や権利を確かめ、他者の価値観だけで決めない。|話しやすい場を整え、必要なら健康状態に合わせた支援につなぐ。|希望があること自体を疾患の症状とみなさない。','sex')
add(95,'退職後の役割の再構築','退職後『人の役に立つ機会が減った』と話す高齢者が、以前は園芸を楽しんでいた。支援はどれか。',4,'以前の職場の役職と同じ地位だけを探す|本人の好みを聞かず多数の活動へ登録する|体力があるので心理面の相談は不要とする|園芸など本人が意味を感じる役割や交流の場を探す','同じ役職に限らず、本人の関心に合う新たな役割を考えられる。|活動の量だけを増やさず、本人が望む内容を確認する。|身体機能が保たれていても、役割の喪失や孤独感を支えることが大切である。|関心や得意なことを生かして、目的やつながりを感じられる活動を一緒に検討する。','social')
add(96,'孤立と孤独感の区別','近所の人と毎日会う高齢者が『心を許して話せる人がいない』と話す。理解として適切なのはどれか。',1,'交流人数が多くても孤独感を抱く場合がある|毎日会話があれば孤独感は生じない|独居している人だけが孤独感を抱く|面会回数だけで孤独感の程度を決められる','客観的な接触の少なさと主観的な寂しさは同一ではなく、本人の気持ちも確認する。|日常的な接触があっても、望むつながりが得られず孤独を感じることがある。|同居家族がいても孤独感が生じる場合がある。|回数だけでなく、関係の質や本人の受け止めを聴く。','social')
add(97,'運転をやめる際の生活支援','運転能力の評価後、高齢者が運転をやめることにしたが、通院と買い物に困ると話す。適切な支援はどれか。',2,'外出目的を減らすことだけを勧める|代替交通や配送等を一緒に確認して生活を支える|免許を返したら地域との交流も終えるよう勧める|交通手段は家族だけで決め本人に知らせない','必要な受診や生活、交流を保てる方法を検討することが重要である。|運転の中止だけで終えず、移動や買い物などの代替手段を整える。|運転しない生活でも、外出や社会とのつながりを保つよう支える。|本人の生活の希望を確認し、実行できる方法を一緒に選ぶ。','drive')
assert len(questions)==30
(root/'data/original/gerontology-root.json').write_text(json.dumps({'category':'老年看護学','sources':sources,'questions':questions},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
